namespace XAminals.Models;

/// <summary>
/// What a page shows when the picture of an animal cannot be loaded (no network, Wikimedia down): the arch of the identity, empty.
/// 112 by 136, a PNG so that every host can draw it (the Razor pages use the same drawing as placeholder.svg).
/// </summary>
public static class ImagePlaceholder
{
    public static byte[] Png => Convert.FromBase64String(Base64);

    private const string Base64 = "";
}
